from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
old='<section id="reports" class="view"><h2>Отчёты</h2><div class="kpi">'
new='<section id="reports" class="view"><h2>Отчёты</h2><div id="reportPeriod" class="period"><button class="chip" data-report-period="1" onclick="setReportPeriod(1)">Сегодня</button><button class="chip" data-report-period="7" onclick="setReportPeriod(7)">7 дней</button><button class="chip" data-report-period="30" onclick="setReportPeriod(30)">30 дней</button><button class="chip" data-report-period="0" onclick="setReportPeriod(0)">Свой период</button></div><div class="kpi">'
if old not in s: raise SystemExit('reports marker missing')
s=s.replace(old,new,1)
old="let selectedPeriodPreset=[0,1,7,30].includes(Number(state.settings.selectedPeriodPreset))?Number(state.settings.selectedPeriodPreset):1;let selectedPeriod=selectedPeriodPreset===0?Math.max(1,Number(state.settings.selectedPeriod)||14):selectedPeriodPreset;"
if old not in s: raise SystemExit('period marker missing')
s=s.replace(old,old+"let reportPeriodPreset=[0,1,7,30].includes(Number(state.settings.reportPeriodPreset))?Number(state.settings.reportPeriodPreset):1;let reportPeriod=reportPeriodPreset===0?Math.max(1,Number(state.settings.reportPeriod)||14):reportPeriodPreset;let marketplaceReportContext=null;",1)
start=s.index('function renderReports(){')
end=s.index('function openProduct(',start)
newcode="""function setReportPeriod(days){reportPeriodPreset=Number(days);if(reportPeriodPreset===0){const d=prompt('Количество дней для своего периода',String(state.settings.reportPeriod||14));if(d===null)return;reportPeriod=Math.max(1,Number(d)||1)}else reportPeriod=reportPeriodPreset;state.settings.reportPeriodPreset=reportPeriodPreset;state.settings.reportPeriod=reportPeriod;save();renderReports()}\nfunction renderReports(){document.querySelectorAll('[data-report-period]').forEach(b=>b.classList.toggle('active',Number(b.dataset.reportPeriod)===reportPeriodPreset));let since=Date.now()-reportPeriod*86400000,ss=financialSales().filter(s=>s.date>=since),rev=ss.reduce((a,s)=>a+(Number(s.qty)||0)*(Number(s.price)||0),0),cost=ss.reduce((a,s)=>a+(Number(s.qty)||0)*(Number(s.cost)||0),0),fees=ss.reduce((a,s)=>a+(Number(s.qty)||0)*(Number(s.fee)||0),0);document.getElementById('rRevenue').textContent=fmt(rev);document.getElementById('rCost').textContent=fmt(cost);document.getElementById('rFees').textContent=fmt(fees);document.getElementById('rProfit').textContent=fmt(rev-cost-fees);let names=['Kaspi','WB','WB2','Ozon','Ручная'];document.getElementById('mpReport').innerHTML=names.map(n=>{let a=ss.filter(s=>s.channel===n),channelRev=a.reduce((x,s)=>x+(Number(s.qty)||0)*(Number(s.price)||0),0),channelProfit=a.reduce((x,s)=>x+(Number(s.qty)||0)*((Number(s.price)||0)-(Number(s.cost)||0)-(Number(s.fee)||0)),0);return `<div class=\"item row\" role=\"button\" tabindex=\"0\" style=\"cursor:pointer\" onclick=\"openMarketplaceReport('${n}',${reportPeriod})\"><div class=\"grow\"><b>${n}</b><div class=\"muted\">${a.reduce((x,s)=>x+(Number(s.qty)||0),0)} шт. · прибыль ${fmt(channelProfit)}</div></div><b>${fmt(channelRev)}</b></div>`}).join('')}\nfunction marketplaceProductStats(market,days=reportPeriod){const since=Date.now()-Math.max(1,Number(days)||1)*86400000,rows=financialSales().filter(s=>s.date>=since&&s.channel===market),map=new Map();for(const sale of rows){const p=prod(sale.productId),key=sale.productId||'unknown',qty=Number(sale.qty)||0,revenue=qty*(Number(sale.price)||0),cost=qty*(Number(sale.cost)||0),fees=qty*(Number(sale.fee)||0);let x=map.get(key);if(!x){x={productId:sale.productId,name:p?.name||'Неизвестный товар',qty:0,revenue:0,cost:0,fees:0,profit:0};map.set(key,x)}x.qty+=qty;x.revenue+=revenue;x.cost+=cost;x.fees+=fees;x.profit+=revenue-cost-fees}return [...map.values()].sort((a,b)=>b.profit-a.profit)}\nfunction openMarketplaceReport(market,days=reportPeriod){marketplaceReportContext={market,days:Math.max(1,Number(days)||1)};renderMarketplaceReportSheet()}\nfunction setMarketplaceReportPeriod(days){if(!marketplaceReportContext)return;let d=Number(days);if(d===0){const x=prompt('Количество дней для своего периода',String(marketplaceReportContext.days||14));if(x===null)return;d=Math.max(1,Number(x)||1)}marketplaceReportContext.days=d;renderMarketplaceReportSheet()}\nfunction renderMarketplaceReportSheet(){const market=marketplaceReportContext?.market,days=Math.max(1,Number(marketplaceReportContext?.days)||1);if(!market)return;const rows=marketplaceProductStats(market,days),qty=rows.reduce((a,x)=>a+x.qty,0),profit=rows.reduce((a,x)=>a+x.profit,0);const periodButtons=`<div class=\"period\" style=\"margin-top:0\"><button class=\"chip ${days===1?'active':''}\" onclick=\"setMarketplaceReportPeriod(1)\">Сегодня</button><button class=\"chip ${days===7?'active':''}\" onclick=\"setMarketplaceReportPeriod(7)\">7 дней</button><button class=\"chip ${days===30?'active':''}\" onclick=\"setMarketplaceReportPeriod(30)\">30 дней</button><button class=\"chip ${![1,7,30].includes(days)?'active':''}\" onclick=\"setMarketplaceReportPeriod(0)\">Свой период</button></div>`;const head=`<div class=\"item\"><div class=\"row\"><div class=\"grow\"><div class=\"label\">Продано</div><div class=\"num\">${qty} шт.</div></div><div class=\"right\"><div class=\"label\">Общая прибыль</div><div class=\"num\">${fmt(profit)}</div></div></div></div>`;const body=rows.length?rows.map((x,i)=>{const unit=x.qty?x.profit/x.qty:0;return `<div class=\"item\" style=\"margin-top:8px;${x.productId?'cursor:pointer':''}\" ${x.productId?`onclick=\"openProduct('${x.productId}','${market}',${days})\"`:''}><div class=\"name\">${i+1}. ${esc(x.name)}</div><div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px\"><div><div class=\"label\">Продано</div><b>${x.qty} шт.</b></div><div><div class=\"label\">Прибыль / шт.</div><b>${fmt(unit)}</b></div><div class=\"right\"><div class=\"label\">Общая прибыль</div><b>${fmt(x.profit)}</b></div></div></div>`}).join(''):'<div class=\"empty\">За выбранный период продаж нет</div>';showSheet(`<h3>Продажи ${esc(market)}</h3>${periodButtons}${head}${body}`)}\n"""
s=s[:start]+newcode+s[end:]
p.write_text(s,encoding='utf-8')
